// FROSTI animation engine, shared by the laptop console and the gallery (the phone has a Kotlin port of the same rules).
//   Rig        draws one frame of penguin E plus props and effects, pixel-snapped.
//   Player     plays one animation: enter -> loop (repeat) -> exit, always starting and ending on REST.
//   Controller turns FROSTI events into the animation that should be on screen, by priority.
// The data lives in frosti_anims.json (generated by author.py).
(function (root) {
"use strict";

class Rig {
  constructor(spec) { this.s = spec; this.pal = spec.palette; }

  // fr: merged frame; pt: ticks into the current part; o: {glow (hex), level 0..1, time (s)}
  draw(g, W, H, fr, pt, o = {}) {
    const s = this.s, [cw, ch] = s.canvas, [gx, gy] = s.origin;
    const u = Math.max(1, Math.floor(Math.min(W / cw, H / ch)));
    this.g = g; this.u = u; this.glitchT = -1;
    this.X0 = Math.round((W - cw * u) / 2) + gx * u; this.Y0 = Math.round((H - ch * u) / 2) + gy * u;
    g.clearRect(0, 0, W, H);
    const glow = o.glow || this.pal.O, lvl = o.level || 0, b = fr.side > 0 ? s.body.side : fr.side < 0 ? this.left() : s.body;
    // walks are authored as 24 cells; stretch anything past 2 so 24 reaches the view's edge (same as CoreView.reach)
    const edge = Math.max(24, W / (2 * u) + 8), ax = Math.abs(fr.dx);
    const bx = ax <= 2 ? fr.dx : Math.sign(fr.dx) * (2 + (ax - 2) * (edge - 2) / 22), by = fr.dy, cr = fr.crouch;
    for (const p of fr.props) if (p.includes("b")) this.prop(p, bx, by);
    if (fr.fx.some(f => f[0] === "glitch")) this.glitchT = Math.floor(pt);
    const K = this.pal.K, Wc = this.pal.W, O = this.pal.O;
    b.feet.forEach(([x, y, w, h], i) => this.rect(x + bx, y + by + fr.ft[i], w, h, O));
    this.rect(b.body[0] + bx, b.body[1] + by + cr, b.body[2], b.body[3], K);
    b.flippers.forEach(([x, y, w, h], i) => this.rect(x + bx, y + by + cr + fr.fl[i], w, h, b.fc ? this.pal[b.fc[i]] : K));
    this.rect(b.belly[0] + bx, b.belly[1] + by + cr, b.belly[2], b.belly[3], Wc);
    const bk = fr.beak === -1 ? lvl : fr.beak, [kx, ky, kw] = b.beak;
    if (bk > .05) { this.rect(kx + bx, ky + by + cr, kw, .5, O); this.rect(kx + bx, ky + .5 + bk * .6 + by + cr, kw, .5, O); }
    else this.rect(kx + bx, ky + by + cr, kw, 1, O);
    b.eyes.forEach((ex, i) => this.eye(fr.eyes, i, ex + fr.lx + bx, by + cr + fr.ly, Wc));
    this.glitchT = -1;
    for (const p of fr.props) if (!p.includes("b")) this.prop(p, bx, by);
    for (const f of fr.fx) this.fx(f, pt, glow, lvl, o.time || 0);
    g.globalAlpha = 1;
  }

  // side=-1: the side-on penguin mirrored to face left (sprite is 16 cells wide)
  left() {
    if (this._left) return this._left;
    const b = this.s.body.side, m = ([x, y, w, h]) => [16 - x - w, y, w, h];
    return this._left = { ...b, body: m(b.body), belly: m(b.belly), beak: m(b.beak), flippers: b.flippers.map(m),
                          feet: b.feet.map(m), eyes: b.eyes.map(x => 15 - x) };
  }

  rect(x, y, w, h, color, a = 1) {
    const g = this.g, u = this.u;
    g.fillStyle = color; g.globalAlpha = a;
    if (this.glitchT >= 0) {  // slice into rows and shift them, like a corrupted frame
      for (let r = Math.floor(y); r < y + h; r++) {
        const top = Math.max(y, r), bot = Math.min(y + h, r + 1), sh = ((hash(r * 31 + this.glitchT) % 3) - 1) * .5;
        this.px(x + sh, top, w, bot - top);
      }
      return;
    }
    this.px(x, y, w, h);
  }
  px(x, y, w, h) {
    const u = this.u, x0 = Math.round(this.X0 + x * u), y0 = Math.round(this.Y0 + y * u);
    this.g.fillRect(x0, y0, Math.round(this.X0 + (x + w) * u) - x0, Math.round(this.Y0 + (y + h) * u) - y0);
  }

  eye(shape, i, x, oy, c) {
    const r = (dx, y, w, h) => this.rect(x + dx, y + oy, w, h, c);
    if (shape === "wink") shape = i ? "closed" : "open";
    if (shape === "confused") shape = i ? "half" : "tall";
    switch (shape) {
      case "blink": return r(0, 3.4, 1, .4);
      case "half": return r(0, 2.8, 1, 1.2);
      case "tall": return r(0, 1.6, 1, 2.6);
      case "up": return r(0, 1.6, 1, 1.4);
      case "down": return r(0, 3, 1, 1.2);
      case "happy": r(-1, 3, 1, 1); r(0, 2, 1, 1); return r(1, 3, 1, 1);
      case "closed": return r(-.5, 3, 2, .6);
      case "x": r(-1, 2, 1, 1); r(1, 2, 1, 1); r(0, 3, 1, 1); r(-1, 4, 1, 1); return r(1, 4, 1, 1);
      case "wide": return r(-.5, 1.5, 2, 2.5);
      default: return r(0, 2, 1, 2);  // open
    }
  }

  prop([name, x, y, flags = ""], bx, by, a = 1) {
    if (flags.includes("h")) { x += bx; y += by; }
    this.glyph(name, x, y, a);
  }
  glyph(name, x, y, a = 1) {
    const rows = this.s.props[name];
    rows.forEach((row, r) => {
      for (let c = 0; c < row.length;) {  // one rect per run of the same colour
        const ch = row[c]; let e = c + 1;
        while (e < row.length && row[e] === ch) e++;
        if (ch !== ".") this.rect(x + c, y + r, e - c, 1, this.pal[ch], a);
        c = e;
      }
    });
  }

  fx(f, pt, glow, lvl, time) {
    const snap = v => Math.round(v * 2) / 2;
    switch (f[0]) {
      case "bars": for (const side of [-1, 1]) for (let k = 0; k < 3; k++) {
        const h = .6 + 2.4 * lvl * (.5 + .5 * Math.abs(Math.sin(time * 9 + k * 1.7 + side)));
        this.rect(8 + side * (9.5 + k * 1.4) - .35, 4 - h / 2, .7, h, glow);
      } break;
      case "rise": { const [, gl, x, y, dx, dy, per, n] = f;
        for (let i = 0; i < n; i++) { const p = (pt / per + i / n) % 1;
          this.glyph(gl, snap(x + dx * p), snap(y + dy * p), Math.min(1, p * 5) * (1 - p)); } break; }
      case "orbit": { const [, gl, cx, cy, rx, ry, per, n] = f;
        for (let i = 0; i < n; i++) { const t = 2 * Math.PI * (pt / per + i / n);
          this.glyph(gl, snap(cx + rx * Math.cos(t) - 1), snap(cy + ry * Math.sin(t) - 1)); } break; }
      case "burst": { const [, x, y, per, n] = f, p = (pt % per) / per, cols = "YRINW";
        for (let k = 0; k < n; k++) { const t = 2 * Math.PI * k / n, r = .5 + 3 * p;
          this.rect(snap(x + Math.cos(t) * r), snap(y + Math.sin(t) * r), 1, 1, this.pal[cols[k % 5]], 1 - p); } break; }
      case "ping": { const [, x, y, per] = f, p = (pt % per) / per, r = .5 + 2 * p, cx = x + .5, cy = y + .5, a = 1 - p;
        this.rect(cx - r, cy - r, 2 * r, .5, glow, a); this.rect(cx - r, cy + r - .5, 2 * r, .5, glow, a);
        this.rect(cx - r, cy - r, .5, 2 * r, glow, a); this.rect(cx + r - .5, cy - r, .5, 2 * r, glow, a); break; }
    }
  }
}

function hash(n) { n = (n ^ 61) ^ (n >>> 16); n = n + (n << 3); n = n ^ (n >>> 4); n = Math.imul(n, 0x27d4eb2d); return (n ^ (n >>> 15)) >>> 0; }

// Frames are deltas over the animation's pose; expand them once per animation.
const EXPANDED = new WeakMap();
function expand(spec, id) {
  let all = EXPANDED.get(spec); if (!all) EXPANDED.set(spec, all = {});
  if (all[id]) return all[id];
  const a = spec.anims[id], out = {}, key = f => { const { n, ...r } = f; return JSON.stringify(r); }, pose = key(a.pose);
  for (const k in a.parts) out[k] = a.parts[k].map(f => ({ ...a.pose, ...f }));
  out.seam = out.loop.map(f => key(f) === pose);  // loop frames that show exactly the pose: safe places to leave
  return all[id] = out;
}

class Player {
  constructor(spec, id) {
    this.spec = spec; this.id = id; this.a = spec.anims[id]; this.P = expand(spec, id);
    this.part = this.P.enter.length ? "enter" : "loop"; this.i = 0; this.t = 0; this.pt = 0; this.loops = 0;
    this.leaving = null; this.done = false; this.speed = 1; this.cover = 0;
  }
  get prio() { return this.a.prio; }
  frame() {
    const f = this.P[this.part][this.i];
    return this.cover > 0 ? { ...f, eyes: "blink" } : f;
  }
  // Ask to stop. Normal: carry on to the next loop frame that shows the pose (the seam), then exit from there.
  // Urgent: cut to the exit now, hide the cut behind a blink, and play the exit at double speed.
  leave(variant = "exit", urgent = false) {
    if (this.done || this.part.startsWith("exit")) return;
    this.leaving = this.P[variant] ? variant : "exit";
    if (urgent) { this.cover = 1; this.speed = 2; this.go(this.leaving); }
    else if (this.part === "loop" && this.P.seam[this.i]) this.go(this.leaving);
  }
  go(part) {
    this.part = part; this.i = 0; this.t = 0; this.pt = 0;
    if (!this.P[part].length) { this.part = "loop"; this.i = this.P.loop.length - 1; this.done = true; }
  }
  step(ticks) {
    if (this.done) return;
    ticks *= this.speed; this.t += ticks; this.pt += ticks;
    if (this.cover > 0) this.cover -= ticks;
    while (!this.done && this.t >= this.P[this.part][this.i].n) {
      this.t -= this.P[this.part][this.i].n;
      if (++this.i < this.P[this.part].length) {
        if (this.leaving && this.part === "loop" && this.P.seam[this.i]) this.go(this.leaving);
        continue;
      }
      if (this.part === "enter") this.go(this.leaving || "loop");
      else if (this.part === "loop") {
        this.loops++;
        const rep = this.a.repeat;
        if (this.leaving || (rep != null && this.loops >= rep)) this.go(this.leaving || "exit");
        else this.go("loop");
      } else { this.i = this.P[this.part].length - 1; this.done = true; }
    }
  }
}

class Controller {
  constructor(spec, opts = {}) {
    this.s = spec; this.m = spec.map; this.T = spec.map.timing; this.rig = new Rig(spec);
    this.rand = opts.rand || Math.random; this.now = 0;
    this.st = "idle"; this.link = opts.link ?? true; this.linkError = false; this.act = null; this.perm = null;
    this.thinkAt = 0; this.sleeping = false; this.look = null; this.queue = []; this.exitVariant = null;
    this.cur = null; this.curOneshot = false; this.nextPastime = this.pastimeDelay(); this.lastStat = {};
    if (opts.walkIn) this.react(this.m.reactions.walk_in);
  }
  pastimeDelay() { return this.now + this.T.pastime_min_ms + this.rand() * (this.T.pastime_max_ms - this.T.pastime_min_ms); }

  // ---- events (all optional; feed whichever the host has) ----
  state(s) { if (s === "thinking" && this.st !== "thinking") this.thinkAt = this.now; this.st = s; }
  activity(tool, args = {}) {
    const t = this.m.tools, sub = tool === "git" ? args.action : tool === "run_project" ? args.task : null;
    this.act = (sub && t[`${tool}:${sub}`]) || t[tool] || "desktop";
  }
  outcome() { this.act = null; }  // the reply that follows picks the reaction
  reply({ tool = null, detail = "", seconds = 0, spoken = false } = {}) {
    const r = this.m.reactions; this.act = null;
    this.react(detail ? r.failed : tool ? (seconds >= this.T.celebrate_s ? r.celebrate : r.done) : spoken ? null : r.chat);
  }
  confirm() { this.perm = this.now; this.exitVariant = null; }
  decided(ok) { this.perm = null; this.exitVariant = ok ? "exit_ok" : "exit_no"; }
  notify() { this.react(this.m.reactions.notify); }
  poke() { this.react(this.m.reactions.poke); }
  surprised() { this.react(this.m.reactions.surprised); }
  hover(look) { this.look = look; }  // -1..1, or null when the pointer leaves
  sleep(on) { this.sleeping = on; }
  setLink(up, error = false) {
    const r = this.m.reactions;
    if (!up && error && !this.linkError) this.react(r.glitch);
    else if (!up && this.link && !error) this.react(r.go_away);
    this.link = up; this.linkError = !up && error;
  }
  stats({ cpu = null, battery = null, charging = false } = {}) {  // each reaction at most once every 10 minutes
    const due = k => !(this.now - (this.lastStat[k] ?? -1e9) < 600000) && (this.lastStat[k] = this.now, true);
    if (cpu != null && cpu > 90 && due("cpu")) this.react(this.m.reactions.overheated);
    if (battery != null && battery < 15 && !charging && due("bat")) this.react(this.m.reactions.low_battery);
  }
  react(id) {
    if (!id) return;
    const v = this.m.variety && this.m.variety[id];  // sometimes play a sibling instead (the original included)
    if (v) { const all = [id, ...v]; id = all[Math.min(all.length - 1, Math.floor(this.rand() * all.length))]; }
    this.queue.push(id);
    this.queue.sort((a, b) => this.s.anims[b].prio - this.s.anims[a].prio);
    this.queue.length = Math.min(this.queue.length, 3);
  }

  // ---- resolution ----
  base() {
    const m = this.m;
    if (this.linkError) return m.states.error;
    if (!this.link) return m.states.offline;
    if (this.perm != null) return this.now - this.perm > this.T.permission_wait_ms ? m.permission_wait : m.permission;
    if (this.st === "listening" || this.st === "speaking") return m.states[this.st];
    if (this.act) return this.act;
    if (this.st === "thinking") return this.now - this.thinkAt > this.T.think_hard_ms ? m.think_hard : m.states.thinking;
    return this.sleeping ? m.states.sleep : m.states.idle;
  }
  want() {
    const b = this.base(), bp = this.s.anims[b].prio;
    while (this.queue.length && this.s.anims[this.queue[0]].prio < bp) this.queue.shift();  // stale: something more important is on
    return this.queue.length ? { id: this.queue[0], oneshot: true } : { id: b, oneshot: false };
  }
  start(w) {
    if (w.oneshot) this.queue.shift();
    this.cur = new Player(this.s, w.id); this.curOneshot = w.oneshot;
  }
  tick(ms) {
    this.now += ms;
    const idle = this.base() === this.m.states.idle;
    if (!idle) this.nextPastime = this.pastimeDelay();
    else if (this.now >= this.nextPastime && !this.queue.length) {
      const p = this.m.pastimes; this.react(p[Math.floor(this.rand() * p.length)]); this.nextPastime = this.pastimeDelay();
    }
    const w = this.want();
    if (!this.cur || this.cur.done) this.start(w);
    else if (w.id !== this.cur.id || (w.oneshot && !this.curOneshot)) {
      const wp = this.s.anims[w.id].prio, cp = this.cur.prio;
      if (!this.curOneshot || wp > cp) {
        const isPerm = this.cur.id === this.m.permission || this.cur.id === this.m.permission_wait;
        const variant = isPerm && this.perm == null && this.exitVariant ? this.exitVariant : "exit";
        this.cur.leave(variant, wp >= 90 && wp > cp);
      }
    }
    this.cur.step(ms / this.s.tick);
    if (this.cur.done) this.start(this.want());
  }
  frame() {
    const f = this.cur.frame();
    return this.look != null && this.cur.id === this.m.states.idle && f.eyes === "open" ? { ...f, lx: Math.round(this.look) } : f;
  }
  draw(g, W, H, o = {}) {
    const a = this.cur.a;
    this.rig.draw(g, W, H, this.frame(), this.cur.pt, { ...o, glow: this.s.palette[a.glow] });
  }
}

const api = { Rig, Player, Controller, expand };
if (typeof module !== "undefined" && module.exports) module.exports = api; else root.Frosti = api;
})(typeof window !== "undefined" ? window : globalThis);
